const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Hong Kong geometry
  const hongKong = ee.Geometry.Point([114.1694, 22.3193]).buffer(30000); // 30km buffer

  // 2. Load Sentinel-5P NO2 data
  const s5p = ee.ImageCollection('COPERNICUS/S5P/NRTI/L3_NO2');

  // 3. Get data for both periods
  const jan = s5p
    .filterDate('2020-01-01', '2020-01-21')
    .filterBounds(hongKong)
    .select('tropospheric_NO2_column_number_density');

  const feb = s5p
    .filterDate('2020-02-10', '2020-02-26')
    .filterBounds(hongKong)
    .select('tropospheric_NO2_column_number_density');

  const janSize = jan.size().getInfo();
  const febSize = feb.size().getInfo();

  console.log(`January images: ${janSize}`);
  console.log(`February images: ${febSize}`);

  if (janSize === 0 || febSize === 0) {
    console.log('Missing data for one or both periods.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Calculate means with quality filtering
  const janMean = jan.mean();
  const febMean = feb.mean();

  // 5. Reduce to get statistics
  const janStats = janMean.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: hongKong,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const febStats = febMean.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: hongKong,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const janValue = janStats.tropospheric_NO2_column_number_density_mean;
  const janCount = janStats.tropospheric_NO2_column_number_density_count;
  const febValue = febStats.tropospheric_NO2_column_number_density_mean;
  const febCount = febStats.tropospheric_NO2_column_number_density_count;

  console.log(`Jan pixels: ${janCount}, Mean NO2: ${janValue}`);
  console.log(`Feb pixels: ${febCount}, Mean NO2: ${febValue}`);

  // 6. Validate results
  if (janCount === 0 || febCount === 0) {
    console.log('No valid pixels after processing.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (janValue === null || febValue === null || 
      isNaN(janValue) || isNaN(febValue) ||
      janValue < 0 || febValue < 0) {
    console.log('Invalid calculation results.');
    console.log('<answer>C3</answer>');
    return;
  }

  // 7. Compare and answer
  console.log(`Change: ${((febValue - janValue) / janValue * 100).toFixed(2)}%`);

  if (febValue < janValue) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
